INSERT INTO _question (id, text, type, category_id, created_id, approval_status) VALUES (90003, 'Đảng Cộng sản Việt Nam khẳng định: Tư tưởng Hồ Chí Minh “là tài sản tinh thần vô cùng to lớn và quý giá của Đảng và dân tộc ta, mãi mãi soi đường cho sự nghiệp cách mạng của nhân dân ta giành thắng lợi” là tại Đại hội lần thứ mấy?', 'MULTIPLE_CHOICE', 90001, 9999, 'PRIVATE');
