INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90015, 'Đại hội Đảng lần thứ VI (1986).', false, 90003);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status) VALUES (90004, 'Đối tượng nghiên cứu của môn học tư tưởng Hồ Chí Minh là:', 'MULTIPLE_CHOICE', 90001, 9999, 'PRIVATE');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90016, 'Nghiên cứu cuộc đời, sự nghiệp của Chủ tịch Hồ Chí Minh.', false, 90004);
