INSERT INTO _question (id, text, type, category_id, created_id, approval_status) VALUES (90015, 'Phương pháp luận nào của việc nghiên cứu tư tưởng Hồ Chí Minh đã yêu cầu, khi nghiên cứu tư tưởng Hồ Chí Minh phải luôn luôn quán triệt mối liên hệ qua lại của các yếu tố, các bộ phận khác nhau trong sự gắn kết tất yếu của hệ thống tư tưởng đó xung quanh hạt nhân cốt lõi là tư tưởng độc lập, tự do, dân chủ và chủ nghĩa xã hội?', 'MULTIPLE_CHOICE', 90001, 9999, 'PRIVATE');
