INSERT INTO _question (id, text, type, category_id, created_id, approval_status) VALUES (90016, 'Đối tượng nào trong chỗ trống ở đoạn viết sau của Hồ Chí Minh: “Cuối thế kỷ XIX chủ nghĩa đế quốc Pháp xâm lược Việt Nam. Bọn ….. đê tiện và hèn nhát đầu hàng và câu kết với bọn đế quốc để tiếp tục nô dịch nhân dân Việt Nam nhiều hơn”.', 'MULTIPLE_CHOICE', 90001, 9999, 'PRIVATE');
