INSERT INTO _question (id, text, type, category_id, created_id, approval_status) VALUES (90017, 'Cuộc cách mạng nào được Hồ Chí Minh đánh giá là “ảnh hưởng đến Việt Nam như tiếng sấm vang trong đêm tối”?', 'MULTIPLE_CHOICE', 90001, 9999, 'PRIVATE');
