INSERT INTO _question (id, text, type, category_id, created_id, approval_status) VALUES (90022, 'Tính chất, đặc điểm của đại từ “Nó” trong câu sau được Hồ Chí Minh dùng để chỉ đối tượng nào: “Nó dùng những người vô sản da trắng để chinh phục những người vô sản các thuộc địa. Sau đó nó lại tung những người vô sản ở một thuộc địa này đi đánh những người vô sản ở một thuộc địa khác. Sau hết, nó dựa vào những người vô sản ở các thuộc địa để thống trị những người vô sản da trắng”:', 'MULTIPLE_CHOICE', 90001, 9999, 'PRIVATE');
