INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90317, 'Đường cách mệnh.', true, 90079);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90318, 'Chánh cương vắn tắt của Đảng.', false, 90079);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status) VALUES (90080, 'Chủ trương “làm tư sản dân quyền cách mạng và thổ địa cách mạng để đi tới xã hội cộng sản” được ghi nhận trong văn kiện nào của Hồ Chí Minh?', 'MULTIPLE_CHOICE', 90002, 9999, 'PRIVATE');
