INSERT INTO _question (id, text, type, category_id, created_id, approval_status) VALUES (90081, 'Chọn đáp án đúng với tư tưởng Hồ Chí Minh:', 'MULTIPLE_CHOICE', 90002, 9999, 'PRIVATE');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90323, 'Cách mạng giải phóng dân tộc cần tiến hành chủ động, sáng tạo.', false, 90081);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90324, 'Cách mạng giải phóng dân tộc cần tiến hành chủ động, sáng tạo và có khả năng giành thắng lợi trước cách mạng vô sản ở chính quốc.', true, 90081);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90325, 'Cách mạng giải phóng dân tộc phụ thuộc vào thắng lợi của cách mạng vô sản ở chính quốc.', false, 90081);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90326, 'Cách cách mạng vô sản ở chính quốc giành thắng lợi đồng thời với cách mạng vô sản ở chính quốc.', false, 90081);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status) VALUES (90082, 'Quan điểm nào sau đây không phải của Hồ Chí Minh?', 'MULTIPLE_CHOICE', 90002, 9999, 'PRIVATE');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90327, 'Trong cuộc đấu tranh chống chủ nghĩa đế quốc, chủ nghĩa thực dân, cách mạng thuộc địa có tầm quan trọng đặc biệt.', true, 90082);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90328, 'Sự giải phóng của giai cấp công nhân phải là sự nghiệp của bản thân giai cấp công nhân.', false, 90082);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90329, 'Công cuộc giải phóng anh em (tức nhân dân thuộc địa) chỉ có thể thực hiện được bằng sự nỗ lực của bản thân anh em.', false, 90082);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90330, 'Cuộc đấu tranh của công nhân ở tất cả các nước để tự giải phóng, chỉ có thể thành công được, nếu công nhân cùng nhau đấu tranh chống lại tư bản quốc tế.', false, 90082);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status) VALUES (90083, 'Trong “Thư kêu gọi tổng khởi nghĩa” (năm 1945), Hồ Chí Minh viết: “Giờ quyết định cho vận mệnh dân tộc ta đã đến. Toàn quốc đồng bào hãy đứng dậy đem sức ta mà…..”. Chọn phương án đúng điền vào chỗ trống.', 'MULTIPLE_CHOICE', 90002, 9999, 'PRIVATE');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90331, 'Xây dựng đất nước ta.', false, 90083);
