INSERT INTO _question (id, text, type, category_id, created_id, approval_status) VALUES (90086, 'Theo Hồ Chí Minh, lực lượng của cách mạng giải phóng dân tộc bao gồm lực lượng nào?', 'MULTIPLE_CHOICE', 90002, 9999, 'PRIVATE');
