INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90345, 'Công – nông – trí thức.', true, 90086);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90346, 'Giai cấp vô sản và nhân dân tiến bộ toàn thế giới.', false, 90086);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status) VALUES (90087, 'Chọn đáp án đúng ở chỗ trống trong câu sau của Hồ Chí Minh: “… mà không tiết kiệm thì khác nào gió vào nhà trống”:', 'MULTIPLE_CHOICE', 90002, 9999, 'PRIVATE');
