INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90354, 'Cả ba phương án kia đều đúng.', false, 90088);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status) VALUES (90089, 'Chọn đáp án đúng ở chỗ trống trong câu sau của Hồ Chí Minh: “Toàn quốc đồng bào hãy đứng dậy ….. mà tự giải phóng cho ta”.', 'MULTIPLE_CHOICE', 90002, 9999, 'PRIVATE');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90355, 'Đem sức ta.', true, 90089);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90356, 'Dưới sự lãnh đạo của Đảng.', false, 90089);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90357, 'Đoàn kết đem sức ta.', false, 90089);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90358, 'Dựa vào sự giúp đỡ của quốc tế.', false, 90089);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status) VALUES (90090, 'Theo Hồ Chí Minh, giải phóng dân tộc là nhiệm vụ hàng đầu của cách mạng ở các nước thuộc địa vì:', 'MULTIPLE_CHOICE', 90002, 9999, 'PRIVATE');
