INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90361, 'Trong giải phóng dân tộc đã bao hàm một phần giải phóng giai cấp.', false, 90090);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90362, 'Cả ba phương án kia đều đúng.', true, 90090);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status) VALUES (90091, 'Quan điểm: “Tất cả các dân tộc trên thế giới đều sinh ra bình đẳng; dân tộc nào cũng có quyền sống, quyền sung sướng và quyền tự do” được Hồ Chí Minh suy ra từ tuyên ngôn nào?', 'MULTIPLE_CHOICE', 90002, 9999, 'PRIVATE');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90363, 'Tuyên ngôn thế giới về quyền con người của Liên Hiệp Quốc, năm 1948.', false, 90091);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90364, 'Tuyên ngôn của Đảng Cộng sản của', false, 90091);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90365, 'Mác và Ph. Ăngghen, năm 1848. C. Tuyên ngôn Nhân quyền và Dân quyền của Cách mạng Pháp, năm 1791.', false, 90091);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90366, 'Tuyên ngôn độc lập của Mỹ, năm 1776.', true, 90091);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status) VALUES (90092, '“Chúng ta tranh được tự do, độc lập rồi mà dân cứ chết đói, chết rét, thì tự do, độc lập cũng không làm gì” nói lên quan điểm nào của Hồ Chí Minh về độc lập dân tộc?', 'MULTIPLE_CHOICE', 90002, 9999, 'PRIVATE');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90367, 'Độc lập dân tộc phải là nền độc lập thật sự, hoàn toàn và triệt để.', false, 90092);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90368, 'Độc lập dân tộc gắn liền với hòa bình, thống nhất và toàn vẹn lãnh thổ.', false, 90092);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90369, 'Độc lập dân tộc phải gắn liền tự do và hạnh phúc của nhân dân.', true, 90092);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90370, 'Cả ba phương án đều đúng.', false, 90092);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status) VALUES (90093, 'Cuộc cách mạng nào được Hồ Chí Minh nhận xét trong tác phẩm “Đường cách mệnh” (1927): “Cách mệnh thành công đã hơn 150 năm nay, nhưng công nông vẫn cứ cực khổ, vẫn cứ lo tính cách mệnh lần thứ hai”?', 'MULTIPLE_CHOICE', 90002, 9999, 'PRIVATE');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90371, 'Cách mạng tư sản Pháp năm 1789.', false, 90093);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90372, 'Cách mạng tư sản Pháp năm 1848.', false, 90093);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90373, 'Cách mạng tư sản Mỹ năm 1776.', true, 90093);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90374, 'Cách mạng Tân Hợi (Trung Quốc) năm 1911.', false, 90093);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status) VALUES (90094, 'Cuộc cách mạng nào được Hồ Chí Minh nhận xét trong tác phẩm “Đường cách mệnh” (1927): “Tiếng là cộng hòa và dân chủ, kỳ thực trong thì nó tước lục công nông, ngoài thì nó áp bức thuộc địa”?', 'MULTIPLE_CHOICE', 90002, 9999, 'PRIVATE');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90375, 'Cách mạng tư sản Pháp năm 1789.', true, 90094);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90376, 'Cách mạng Tân Hợi ở Trung Quốc năm 1911.', false, 90094);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90377, 'Cách mạng giải phóng dân tộc Mỹ năm 1776.', false, 90094);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status) VALUES (90095, 'Theo quan điểm của Hồ Chí Minh, đối tượng của cách mạng ở thuộc địa là ai?', 'MULTIPLE_CHOICE', 90002, 9999, 'PRIVATE');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90378, 'Là giai cấp tư sản bản xứ.', false, 90095);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90379, 'Là giai cấp địa chủ nói chung.', false, 90095);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90380, 'Là chủ nghĩa thực dân và tay sai phản động.', false, 90095);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90381, 'Mọi giai cấp, tầng lớp bóc lột trong xã hội.', true, 90095);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status) VALUES (90096, 'Quan điểm sau đây của Hồ Chí Minh được nêu tại Đại hội/Hội nghị của Đảng: “Cuộc cách mạng Đông Dương hiện tại không phải là cuộc cách mạng tư sản dân quyền, cuộc cách mạng phải giải quyết hai vấn đề: phản đế và điền địa nữa, mà là một cuộc cách mạng chỉ phải giải quyết một vấn đề cần kíp “dân tộc giải phóng”?', 'MULTIPLE_CHOICE', 90002, 9999, 'PRIVATE');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90382, 'Hội nghị thành lập Đảng (1930).', false, 90096);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90383, 'Đại hội lần thứ nhất của Đảng (3/1935).', false, 90096);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90384, 'Hội nghị Trung ương Đảng lần thứ 7 (11/1940).', false, 90096);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90385, 'Hội nghị Trung ương Đảng lần thứ tám (5/1941).', true, 90096);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status) VALUES (90097, 'Nhận định sau đây của Hồ Chí Minh trong tác phẩm nào: “Dù sao, chúng ta phải quyết tâm đánh giặc Mỹ đến thắng lợi hoàn toàn. Còn non, còn nước còn người. Thắng giặc Mỹ, ta sẽ xây dựng hơn mười ngày nay!”?', 'MULTIPLE_CHOICE', 90002, 9999, 'PRIVATE');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90386, 'Lời kêu gọi của Hồ Chí Minh (17/7/1966).', false, 90097);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90387, 'Đường cách mệnh (1927).', false, 90097);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90388, 'Di chúc (1965-1969).', true, 90097);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90389, 'Thư khen đồng bào, chiến sĩ và cán bộ miền Nam (8/9/1968).', false, 90097);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status) VALUES (90098, 'Tại Đại hội V Quốc tế cộng sản (1924), Hồ Chí Minh đã chỉ rõ: Vận mệnh của giai cấp vô sản ở các nước đi xâm lược thuộc địa gắn chặt với vận mệnh của ai?', 'MULTIPLE_CHOICE', 90002, 9999, 'PRIVATE');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90390, 'Vận mệnh của các dân tộc thuộc địa.', false, 90098);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90391, 'Vận mệnh của giai cấp bị áp bức ở các thuộc địa.', true, 90098);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90392, 'Vận mệnh của giai cấp nông dân ở các thuộc địa.', false, 90098);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90393, 'Vận mệnh của giai cấp vô sản ở các thuộc địa.', false, 90098);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status) VALUES (90099, 'Trong cách mạng giải phóng dân tộc, Hồ Chí Minh xác định lực lượng nào là gốc của cách mạng?', 'MULTIPLE_CHOICE', 90002, 9999, 'PRIVATE');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90394, 'Công nhân, trí thức.', false, 90099);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90395, 'Nông dân, tư sản.', false, 90099);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90396, 'Công nhân, tiểu tư sản.', false, 90099);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90397, 'Công nhân, nông dân.', true, 90099);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status) VALUES (90100, 'Trong bài “Cách mạng Tháng Mười vĩ đại mở ra con đường giải phóng cho các dân tộc” (năm 1967), Hồ Chí Minh nhận định: “Trong cuộc đấu tranh gian khổ chống kẻ thù của giai cấp và của dân tộc, cần dùng …. chống lại bạo lực phản cách mạng, giành lấy chính quyền và bảo vệ chính quyền”. Chọn phương án đúng điền vào chỗ trống.', 'MULTIPLE_CHOICE', 90002, 9999, 'PRIVATE');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90398, 'Đấu tranh nghị trường.', false, 90100);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90399, 'Bạo lực cách mạng.', true, 90100);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90400, 'Lực lượng toàn dân.', false, 90100);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90401, 'Đấu tranh hòa bình.', false, 90100);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status) VALUES (90101, 'Theo Hồ Chí Minh, điều kiện tiên quyết để tiến lên xây dựng chủ nghĩa xã hội là:', 'MULTIPLE_CHOICE', 90002, 9999, 'PRIVATE');
