INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90403, 'Có sự lãnh đạo của Đảng.', false, 90101);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90404, 'Tiền vốn, khoa học – kỹ thuật.', false, 90101);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90405, 'Sự đoàn kết toàn dân.', false, 90101);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status) VALUES (90102, 'Chọn đáp án đúng ở chỗ trống trong câu sau của Hồ Chí Minh: “Chỉ tiêu kế hoạch một phần, …. phải hai phần, cố gắng phải ba phần”:', 'MULTIPLE_CHOICE', 90002, 9999, 'PRIVATE');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90406, 'Trách nhiệm.', false, 90102);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90407, 'Sáng kiến.', false, 90102);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90408, 'Quyết tâm.', false, 90102);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90409, 'Biện pháp.', true, 90102);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status) VALUES (90103, 'Mục tiêu cụ thể của về kinh tế trong thời kỳ quá độ lên chủ nghĩa xã hội ở Việt Nam theo tư tưởng Hồ Chí Minh là gì?', 'MULTIPLE_CHOICE', 90002, 9999, 'PRIVATE');
