INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90418, 'Khoa học kỹ thuật tiên tiến.', false, 90105);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90419, 'Kinh tế phát triển.', false, 90105);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90420, 'Giải phóng giai cấp, giải phóng con người.', false, 90105);
