INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90422, 'Một nền kinh tế hiện đại.', false, 90106);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90423, 'Phát triển mạnh mẽ khoa học – kỹ thuật.', false, 90106);
