INSERT INTO _question (id, text, type, category_id, created_id, approval_status) VALUES (90107, 'Theo Hồ Chí Minh, động lực quyết định nhất của chủ nghĩa xã hội là', 'MULTIPLE_CHOICE', 90002, 9999, 'PRIVATE');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90426, 'Khoa học - kỹ thuật.', false, 90107);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90427, 'Chính trị.', false, 90107);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90428, 'Con người.', true, 90107);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90429, 'Sự giúp đỡ, ủng hộ quốc tế.', false, 90107);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status) VALUES (90108, 'Theo tư tưởng Hồ Chí Minh, động lực quan trọng và quyết định của của chủ nghĩa xã hội ở Việt Nam là gì?', 'MULTIPLE_CHOICE', 90002, 9999, 'PRIVATE');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90430, 'Đấu tranh giai cấp, cải tạo xã hội cũ, xây dựng xã hội mới.', false, 90108);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90431, 'Là con người, là nhân dân lao động mà nòng cốt là công – nông – trí thức.', true, 90108);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90432, 'Thực hiện bình đẳng và công bằng xã hội.', false, 90108);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90433, 'Xóa đói giảm nghèo.', false, 90108);
