INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90434, 'Sự tàn bạo của chủ nghĩa tư bản đã chuẩn bị đất rồi. Chủ nghĩa xã hội chỉ còn phải làm cái việc là gieo hạt giống của công cuộc giải phóng nữa thôi.', true, 90109);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90435, 'Xem xét lại chủ nghĩa Mác về cơ sở lịch sử của nó, củng cố nó bằng dân tộc học phương Đông.', false, 90109);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90436, 'Chủ nghĩa dân tộc là động lực lớn của đất nước.', false, 90109);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90437, 'Cả ba phương án kia đều đúng', false, 90109);
