INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90440, 'Chủ nghĩa đế quốc.', false, 90110);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90441, 'Chủ nghĩa cá nhân.', true, 90110);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status) VALUES (90111, 'Quan điểm của Hồ Chí Minh về động lực xây dựng chủ nghĩa xã hội ở Việt Nam là gì?', 'MULTIPLE_CHOICE', 90002, 9999, 'PRIVATE');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90442, 'Động lực bên trong.', false, 90111);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90443, 'Động lực bên ngoài.', false, 90111);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90444, 'Ngăn ngừa “giặc nội xâm” là tham ô, lãng phí, quan liêu, các yếu tố kìm hãm, triệt tiêu nguồn lực vốn có của chủ nghĩa xã hội.', false, 90111);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90445, 'Cả ba phương án kia đều đúng.', true, 90111);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status) VALUES (90112, 'Quan điểm của Hồ Chí Minh về động lực quan trọng và quyết định xây dựng chủ nghĩa xã hội ở Việt Nam là gì?', 'MULTIPLE_CHOICE', 90002, 9999, 'PRIVATE');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90446, 'Sức mạnh thời đại, của tinh thần đoàn kết quốc tế.', false, 90112);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90447, 'Sức mạnh của các thành quả khoa học - kỹ thuật thế giới.', false, 90112);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90448, 'Sức mạnh vật chất và tinh thần của con người, của nhân dân lao động mà nòng cốt là công - nông - trí thức.', false, 90112);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90449, 'Cả ba phương án kia đều đúng.', true, 90112);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status) VALUES (90113, 'Đặc điểm to nhất khi Việt Nam quá độ lên chủ nghĩa xã hội theo tư tưởng Hồ Chí Minh là:', 'MULTIPLE_CHOICE', 90002, 9999, 'PRIVATE');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90450, 'Từ một nước thuộc địa, nửa phong kiến, trình độ pháp luật còn kém', false, 90113);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90451, 'Từ một nước nông nghiệp lạc hậu tiến thẳng lên chủ nghĩa xã hội, không kinh qua giai đoạn phát triển tư bản chủ nghĩa.', true, 90113);
