INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90453, 'Từ một nước thuộc địa, nửa phong kiến, nông nghiệp lạc hậu.', false, 90113);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status) VALUES (90114, 'Theo Hồ Chí Minh, động lực quan trọng nhất của cách mạng xã hội chủ nghĩa Việt Nam là:', 'MULTIPLE_CHOICE', 90002, 9999, 'PRIVATE');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90454, 'Động lực kinh tế.', false, 90114);
