INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90458, 'Mâu thuẫn giữa nghèo đói sau chiến tranh và đòi hỏi nâng cao đời sống nhân', false, 90115);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90459, 'Mâu thuẫn giữa nhu cầu phát triển cao của đất nước theo xu hướng tiến bộ và thực trạng kinh tế - xã hội quá thấp kém của nước ta.', true, 90115);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90460, 'Mâu thuẫn giữa ổn định xã hội và sự phá hoại của các thế lực thù địch.', false, 90115);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90461, 'Mâu thuẫn giữa trình độ khoa học kỹ thuật của ta thấp kém và nhu cầu hội nhập kinh tế thế giới.', false, 90115);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status) VALUES (90116, 'Ngày 24/4/1957, khi nói chuyện với cán bộ, công nhân nhà máy dệt Nam Định, Hồ Chí Minh cho rằng: “Chế độ làm khoán là một điều kiện của chủ nghĩa xã hội, nó khuyến khích người công nhân luôn luôn tiến bộ, cho nhà máy tiến bộ. Làm khoán là ……”. Chọn phương án đúng điền vào chỗ trống.', 'MULTIPLE_CHOICE', 90002, 9999, 'PRIVATE');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90462, 'Tạo điều kiện phát triển sản xuất.', false, 90116);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90463, 'Ích chung và lại lợi riêng.', false, 90116);
