INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90465, 'Cả ba phương án kia đều đúng.', true, 90116);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status) VALUES (90117, 'Theo Hồ Chí Minh, trong điều kiện của nước ta, biện pháp cơ bản, quyết định, lâu dài trong xây dựng chủ nghĩa xã hội là gì?', 'MULTIPLE_CHOICE', 90002, 9999, 'PRIVATE');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90466, 'Đem tài dân, sức dân, của dân làm lợi cho dân dưới sự lãnh đạo của Đảng.', true, 90117);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90467, 'Tiến hành công nghiệp hóa.', false, 90117);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90468, 'Xây dựng đội ngũ lãnh đạo đủ đức và tài.', false, 90117);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90469, 'Phát triển khoa học kỹ thuật.', false, 90117);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status) VALUES (90118, 'Theo Hồ Chí Minh, biện pháp để tiến hành xây dựng chủ nghĩa xã hội ở Việt Nam là gì?', 'MULTIPLE_CHOICE', 90002, 9999, 'PRIVATE');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90470, 'Thực hiện cải tạo xã hội cũ, xây dựng xã hội mới, kết hợp cải tạo với xây dựng, lấy xây dựng làm chính.', false, 90118);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90471, 'Kết hợp xây dựng và bảo vệ, đồng thời tiến hành hai nhiệm vụ chiến lược ở hai miền Nam - Bắc khác nhau trong phạm vi một quốc gia.', false, 90118);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90472, 'Biện pháp cơ bản, quyết định, lâu dài trong xây dựng chủ nghĩa xã hội là đem của dân, tài dân, sức dân, làm lợi cho dân dưới sự lãnh đạo của Đảng.', false, 90118);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90473, 'Cả ba phương án kia đều đúng.', true, 90118);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status) VALUES (90119, 'Quan điểm của Hồ Chí Minh về mối quan hệ giữa nội lực và ngoại lực xây dựng chủ nghĩa xã hội ở Việt Nam?', 'MULTIPLE_CHOICE', 90002, 9999, 'PRIVATE');
