INSERT INTO _question (id, text, type, category_id, created_id, approval_status) VALUES (90122, 'Tư tưởng "Đem tài dân, sức dân, của dân làm lợi cho dân" là nói đến mặt nào trong đặc trưng xã hội xã hội chủ nghĩa của Hồ Chí Minh?', 'MULTIPLE_CHOICE', 90003, 9999, 'PRIVATE');
