INSERT INTO _question (id, text, type, category_id, created_id, approval_status) VALUES (90126, 'Quan điểm sau đây về quy luật hình thành Đảng Cộng sản là của ai: “Đảng Cộng sản ra đời là sản phẩm của sự kết hợp giữa chủ nghĩa Mác với phong trào công nhân”.', 'MULTIPLE_CHOICE', 90003, 9999, 'PRIVATE');
