INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90683, 'Đảng đáp ứng nhu cầu tất yếu của xã hội Việt Nam.', false, 90171);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90684, 'Đảng hoạt động vì nước vì dân.', false, 90171);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status) VALUES (90172, 'Theo Hồ Chí Minh, nguyên tắc nào trong hoạt động của Đảng phải là việc làm thường xuyên, như “mỗi ngày phải rửa mặt”.', 'MULTIPLE_CHOICE', 90004, 9999, 'PRIVATE');
