INSERT INTO _question (id, text, type, category_id, created_id, approval_status) VALUES (90174, 'Tư tưởng về đảng kiểu mới của giai cấp vô sản, được Hồ Chí Minh vận dụng, phát triển trong quá trình sáng lập và rèn luyện Đảng Cộng sản Việt Nam là tư tưởng của ai?', 'MULTIPLE_CHOICE', 90004, 9999, 'PRIVATE');
