INSERT INTO _question (id, text, type, category_id, created_id, approval_status) VALUES (90178, 'Theo Hồ Chí Minh, tổ chức nào là “hạt nhân”, quyết định chất lượng lãnh đạo của Đảng, là môi trường tu dưỡng, rèn luyện và cũng là nơi giám sát đảng viên?', 'MULTIPLE_CHOICE', 90004, 9999, 'PRIVATE');
