INSERT INTO _question (id, text, type, category_id, created_id, approval_status) VALUES (90181, 'Theo Hồ Chí Minh, trong xây dựng Đảng về chính trị, vấn đề nào là “cốt tử”?', 'MULTIPLE_CHOICE', 90004, 9999, 'PRIVATE');
