INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90735, 'Đoàn kết thống nhất thành một khối.', false, 90184);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status) VALUES (90185, 'Tại Hội nghị Đại biểu Mặt trận Liên - Việt (10/1/1955), Hồ Chí Minh cho rằng: đại đoàn kết trước hết phải đoàn kết đa số nhân dân. Vậy đại đa số nhân dân là những ai?', 'MULTIPLE_CHOICE', 90004, 9999, 'PRIVATE');
