INSERT INTO _question (id, text, type, category_id, created_id, approval_status) VALUES (90210, 'Hồ Chí Minh đã giương cao ngọn cờ nào khi đoàn kết giữa cách mạng Việt Nam với các lực lượng tiến bộ trên thế giới?', 'MULTIPLE_CHOICE', 90004, 9999, 'PRIVATE');
