INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90843, 'Tôn trọng chủ quyền, toàn vẹn lãnh thổ.', false, 90211);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status) VALUES (90212, 'Theo Hồ Chí Minh, Mặt trận dân tộc thống nhất phải đặt dưới sự lãnh đạo của ai?', 'MULTIPLE_CHOICE', 90004, 9999, 'PRIVATE');
