INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90847, 'Đảng Cộng sản Việt Nam.', true, 90212);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status) VALUES (90213, 'Theo Hồ Chí Minh, bản chất của các đoàn thể, tổ chức quần chúng nhân dân là:', 'MULTIPLE_CHOICE', 90004, 9999, 'PRIVATE');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90848, 'Tổ chức của Đảng.', false, 90213);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90849, 'Tổ chức của Nhà nước.', false, 90213);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90850, 'Tổ chức của Dân.', true, 90213);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90851, 'Tổ chức của Quốc tế cộng sản.', false, 90213);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status) VALUES (90214, 'Nền văn hóa mới mà chúng ta xây dựng theo tư tưởng Hồ Chí Minh bao gồm tính dân tộc, tính đại chúng và tính chất gì?', 'MULTIPLE_CHOICE', 90004, 9999, 'PRIVATE');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90852, 'Hiện đại.', false, 90214);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90853, '*B. Khoa học.', false, 90214);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90854, 'Tiên tiến.', false, 90214);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90855, 'Xã hội chủ nghĩa.', false, 90214);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status) VALUES (90215, 'Theo Hồ Chí Minh, phải làm cho văn hóa thấm sâu vào tâm lý quốc dân, nghĩa là văn hóa phải sửa đổi được thói hư, tật xấu gì?', 'MULTIPLE_CHOICE', 90004, 9999, 'PRIVATE');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90856, 'Tham nhũng.', false, 90215);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90857, 'Tham nhũng, lười biếng.', false, 90215);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90858, 'Phù hoa, xa xỉ.', false, 90215);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90859, 'Tham nhũng, lười biếng, phù hoa, xa xỉ.', true, 90215);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status) VALUES (90216, 'Tại Đại hội đại biểu toàn quốc lần thứ II của Đảng (1951), Hồ Chí Minh khẳng định, nền văn hóa Việt Nam bao gồm những tính chất nào?', 'MULTIPLE_CHOICE', 90004, 9999, 'PRIVATE');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90860, 'Dân tộc, hiện đại.', false, 90216);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90861, 'Hiện đại, đậm đà bản sắc dân tộc.', false, 90216);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90862, 'Dân tộc, khoa học, đại chúng.', true, 90216);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90863, 'Có nội dung xã hội chủ nghĩa và tính chất dân tộc.', false, 90216);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status) VALUES (90217, 'Theo tư tưởng Hồ Chí Minh, văn hóa với chính trị có quan hệ chặt chẽ với nhau. Có chính trị mới có văn hóa, xưa kia chính trị bị đàn áp, nền văn hóa của ta vì thế không nảy sinh được. Nay nước ta đã độc lập, tinh thần được giải phóng, cần phải có một nền văn hóa hợp với khoa học và hợp cả với nguyện vọng của ai?', 'MULTIPLE_CHOICE', 90004, 9999, 'PRIVATE');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90864, 'Nguyện vọng của giai cấp công nhân.', false, 90217);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90865, 'Nguyện vọng của công – nông.', false, 90217);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90866, 'Nguyện vọng của công – nông – trí thức.', true, 90217);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90867, 'Nguyện vọng của dân.', false, 90217);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status) VALUES (90218, 'Quan điểm nào sau đây không phải của Hồ Chí Minh về chức năng của văn hóa?', 'MULTIPLE_CHOICE', 90004, 9999, 'PRIVATE');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90868, 'Bồi dưỡng tư tưởng đúng đắn và những tình cảm cao đẹp cho nhân dân.', false, 90218);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90869, 'Mở rộng hiểu biết, nâng cao dân trí.', false, 90218);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90870, 'Bồi dưỡng những phẩm chất, phong cách và lối sống tốt đẹp, lành mạnh; hướng đến chân, thiện, mỹ để hoàn thiện bản thân.', false, 90218);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90871, 'Dân tộc, khoa học và đại chúng.', true, 90218);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status) VALUES (90219, 'Câu sau thể hiện quan điểm của Hồ Chí Minh về lĩnh vực nào: “Vì lẽ sinh tồn cũng như mục đích của cuộc sống, loài người mới sáng tạo và phát minh ra ngôn ngữ, chữ viết, đạo đức, pháp luật, khoa học, tôn giáo, văn học, nghệ thuật, những công cụ cho sinh hoạt hằng ngày về mặc, ăn, ở và các phương thức sử dụng”.', 'MULTIPLE_CHOICE', 90004, 9999, 'PRIVATE');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90872, 'Khoa học.', false, 90219);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90873, 'Văn hóa.', true, 90219);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90874, 'Xã hội.', false, 90219);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90875, 'Kinh tế.', false, 90219);
INSERT INTO categories (id, name, creator_id, is_public, parent_id) VALUES (90005, 'Chương 5', 9999, true, 90000);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status) VALUES (90220, 'Phương án nào sau đây không phải của Hồ Chí Minh về phương châm, phương pháp giáo dục?', 'MULTIPLE_CHOICE', 90005, 9999, 'PRIVATE');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90876, 'Học đi đôi với hành. Lý luận liên hệ với thực tế.', false, 90220);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90877, 'Học tập kết hợp với lao động. Phối hợp nhà trường - gia đình - xã hội.', false, 90220);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90878, 'Thực hiện dân chủ, bình đẳng trong giáo dục.', true, 90220);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90879, 'Học, học nữa, học mãi.', false, 90220);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status) VALUES (90221, 'Sau Cách mạng 8/1945, Hồ Chí Minh cho rằng: Chúng ta có nhiệm vụ cấp bách là phải giáo dục lại nhân dân chúng ta… làm cho dân tộc chúng ta trở nên một dân tộc dũng cảm, yêu nước, yêu lao động, một dân tộc xứng đáng với nước Việt Nam độc lập. Người đề nghị mở một chiến dịch giáo dục lại tinh thần nhân dân bằng cách thực hiện gì?', 'MULTIPLE_CHOICE', 90005, 9999, 'PRIVATE');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90880, 'Thực hiện phong trào xóa nạn mù chữ.', false, 90221);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90881, 'Mở rộng hiểu biết, nâng cao dân trí.', false, 90221);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90882, 'Thực hiện: cần, kiệm, liêm, chính.', true, 90221);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90883, 'Gắn liền với lao động sản xuất.', false, 90221);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status) VALUES (90222, 'Ngày 3/9/1945, trong phiên họp đầu tiên của Hội đồng Chính phủ, Hồ Chí Minh nêu 6 nhiệm vụ cấp bách của nhà nước Việt Nam Dân chủ Cộng hòa. Trong đó, ở vấn đề thứ tư, Người đề nghị mở một chiến dịch giáo dục lại tinh thần nhân dân bằng cách thực hiện gì?', 'MULTIPLE_CHOICE', 90005, 9999, 'PRIVATE');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90884, 'Tự phê bình và phê bình.', false, 90222);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90885, 'Chủ nghĩa yêu nước.', false, 90222);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90886, 'Cần, Kiệm, Liêm, Chính.', true, 90222);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90887, 'Đoàn kết.', false, 90222);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status) VALUES (90223, 'Chọn phương án đúng điền vào chỗ trống ở câu sau của Hồ Chí Minh về con người: “Chữ người, nghĩa hẹp là ..... , anh em, họ hàng, bầu bạn. Nghĩa rộng là ..... cả nước. Rộng nữa là cả ..... ”.', 'MULTIPLE_CHOICE', 90005, 9999, 'PRIVATE');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90888, 'Nhân dân/ dân tộc/ nhân loại.', false, 90223);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90889, 'Gia đình/ người dân/ con người.', false, 90223);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90890, 'Gia đình/đồng bào/ loài người.', true, 90223);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90891, 'Cha mẹ/ đồng bào/ người cùng khổ.', false, 90223);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status) VALUES (90224, 'Theo Hồ Chí Minh, muốn xây dựng chủ nghĩa xã hội, trước hết cần phải có yếu tố nào sau đây?', 'MULTIPLE_CHOICE', 90005, 9999, 'PRIVATE');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90892, 'Tài nguyên..', false, 90224);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90893, 'Con người xã hội chủ nghĩa.', true, 90224);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90894, 'Tiền vốn.', false, 90224);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90895, 'Khoa học kỹ thuật.', false, 90224);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status) VALUES (90225, 'Theo Hồ Chí Minh, CẦN, KIỆM, LIÊM, CHÍNH là nền tảng của:', 'MULTIPLE_CHOICE', 90005, 9999, 'PRIVATE');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90896, 'Đạo đức mới.', false, 90225);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90897, 'Thi đua ái quốc.', false, 90225);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90898, 'Đạo đức mới và Đời sống mới.', false, 90225);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90899, 'Đời sống mới và Thi đua ái quốc.', true, 90225);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status) VALUES (90226, 'Theo Hồ Chí Minh, người cách mạng là “phải biết làm cho phần tốt ở trong mỗi con người nẩy nở như hoa mùa xuân và phần xấu bị mất dần đi”. Đó là thái độ của người cách mạng đối với điều gì trong lòng mỗi người?', 'MULTIPLE_CHOICE', 90005, 9999, 'PRIVATE');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90900, 'Chủ nghĩa cá nhân.', false, 90226);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90901, 'Đạo đức cách mạng và đạo đức cũ.', false, 90226);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90902, 'Tốt - Xấu.', false, 90226);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90903, 'Thiện - Ác.', true, 90226);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status) VALUES (90227, 'Quan điểm xây dựng nền văn hóa có nội dung xã hội chủ nghĩa và tính chất dân tộc được Hồ Chí Minh nêu ra vào thời gian nào?', 'MULTIPLE_CHOICE', 90005, 9999, 'PRIVATE');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90904, 'Năm 1941.', false, 90227);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90905, 'Năm 1945.', false, 90227);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90906, 'Năm 1951.', false, 90227);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90907, 'Năm 1960. là:', true, 90227);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status) VALUES (90228, 'Hồ Chí Minh lưu ý rằng, đấu tranh chống chủ nghĩa cá nhân nghĩa', 'MULTIPLE_CHOICE', 90005, 9999, 'PRIVATE');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90908, 'Chỉ bảo vệ lợi ích tập thể.', false, 90228);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90909, 'Xóa bỏ lợi ích cá nhân.', false, 90228);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90910, 'Không phải “giày xéo lên lợi ích cá nhân”.', true, 90228);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90911, 'Cân bằng giữa lợi ích quốc gia với lợi ích cá nhân.', false, 90228);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status) VALUES (90229, 'Bản chất của tư tưởng đạo đức Hồ Chí Minh là gì?', 'MULTIPLE_CHOICE', 90005, 9999, 'PRIVATE');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90912, 'Đạo đức tư sản.', false, 90229);
