INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90915, 'Đạo đức phong kiến.', false, 90229);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status) VALUES (90230, 'Theo Hồ Chí Minh, văn hóa là:', 'MULTIPLE_CHOICE', 90005, 9999, 'PRIVATE');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90916, 'Những sáng tạo và phát minh của loài người về ngôn ngữ, chữ viết, đạo đức, pháp luật, khoa học, tôn giáo, văn học, nghệ thuật.', false, 90230);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90917, 'Những công cụ cho sinh hoạt hằng ngày về mặc, ăn, ở do loài người sáng tạo và phát minh ra.', false, 90230);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90918, 'Những sáng tạo và phát minh của loài người về các phương thức sử dụng.', false, 90230);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90919, 'Cả ba phương án kia đều đúng.', true, 90230);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status) VALUES (90231, 'Quan điểm của Hồ Chí Minh về vị trí và vai trò của văn hóa trong đời sống xã hội: “Xã hội thế nào, văn hóa thế ấy. Văn nghệ của dân tộc ta vốn rất phong phú, nhưng dưới chế độ thực dân và phong kiến nhân dân ta bị nô lệ thì văn nghệ cũng bị nô lệ, bị tồi tàn không thể phát triển được”, “Rõ ràng là dân tộc bị áp bức thì văn nghệ cũng mất tự do. Văn nghệ muốn tự do thì phải ….. ”. Chọn phương án đúng điền vào chỗ trống.', 'MULTIPLE_CHOICE', 90005, 9999, 'PRIVATE');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90920, 'Nước nhà độc lập.', false, 90231);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90921, 'Tham gia cách mạng.', false, 90231);
