INSERT INTO _question (id, text, type, category_id, created_id, approval_status) VALUES (90256, 'Theo Hồ Chí Minh đạo đức cách mạng là một phạm trù lịch sử, nghĩa là nó cũng thay đổi theo nhiệm vụ từng thời kỳ của cách mạng, “đạo đức xã hội chủ nghĩa không phải ở đâu cũng biểu hiện giống nhau. Ở nước ta đạo đức xã hội chủ nghĩa là …..”. Chọn phương án đúng điền vào chỗ trống.', 'MULTIPLE_CHOICE', 90005, 9999, 'PRIVATE');
