INSERT INTO _question (id, text, type, category_id, created_id, approval_status) VALUES (90260, 'Nhận định sau đây của Hồ Chí Minh trong bài viết/bài nói nào: “Một dân tộc dốt là một dân tộc yếu”?', 'MULTIPLE_CHOICE', 90005, 9999, 'PRIVATE');
