INSERT INTO _question (id, text, type, category_id, created_id, approval_status) VALUES (90261, 'Chọn phương án đúng điền vào chỗ trống trong câu sau của Hồ Chí Minh về vai trò của văn hóa: “Văn hóa ... cho quốc dân đi”.', 'MULTIPLE_CHOICE', 90005, 9999, 'PRIVATE');
