INSERT INTO _question (id, text, type, category_id, created_id, approval_status) VALUES (90262, 'Nội dung xây dựng con người xã hội chủ nghĩa theo tư tưởng Hồ Chí Minh gồm:', 'MULTIPLE_CHOICE', 90005, 9999, 'PRIVATE');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (91044, 'Có ý thức làm chủ, tinh thần tập thể xã hội chủ nghĩa và tư tưởng “mình vì mọi người, mọi người vì mình”.', false, 90262);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (91045, 'Cần kiệm xây dựng đất nước, hăng hái bảo vệ Tổ quốc; Có lòng yêu nước nồng nàn, tinh thần quốc tế trong sáng.', false, 90262);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (91046, 'Có phương pháp làm việc khoa học, phong cách quần chúng, dân chủ, nêu gương.', false, 90262);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (91047, 'Cả ba phương án kia đều đúng.', true, 90262);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status) VALUES (90263, 'Theo Hồ Chí Minh, tinh thần quốc tế trong sáng được hiểu là:', 'MULTIPLE_CHOICE', 90005, 9999, 'PRIVATE');
