INSERT INTO _question (id, text, type, category_id, created_id, approval_status) VALUES (90264, 'Luận điểm nào dưới đây được Hồ Chí Minh nói về chức năng của văn', 'MULTIPLE_CHOICE', 90005, 9999, 'PRIVATE');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (91052, 'Văn hóa phải nâng cao dân trí.', true, 90264);
