INSERT INTO _answer (id, text, is_correct, question_id) VALUES (91067, 'Đấu tranh cho hòa bình, thống nhất và độc lập dân tộc.', false, 90267);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status) VALUES (90268, 'Chọn phương án đúng vào chỗ trống trong câu sau của Hồ Chí Minh: “Người đi giáo dục ….. phải học thêm mãi, học không bao giờ đủ, còn sống còn phải học”.', 'MULTIPLE_CHOICE', 90005, 9999, 'PRIVATE');
