INSERT INTO _question (id, text, type, category_id, created_id, approval_status) VALUES (90867, 'Vùng biển Bắc cực được luật lệ Công pháp quốc tế xác định theo phương án nào sau đây ?', 'MULTIPLE_CHOICE', 90018, 9999, 'PRIVATE');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (93462, 'Các quốc gia giáp với vùng Bắc cực có được một phần nội thủy và lãnh hải có chiều rộng 12 hải lý tính từ ranh giới quốc gia hướng tới Bắc cực;', false, 90867);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (93463, 'Các quốc gia vành đai giáp với Bắc cực có được một phần lãnh thổ theo quy tắc phù hợp với Công pháp quốc tế tính từ mốc quốc giới ngoài cùng của quốc gia hướng tới tâm Bắc cực;', true, 90867);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (93464, 'Các quốc gia vành đai giáp với vùng Bắc cực có được một phần lãnh thổ mở rộng có chiều dài 200 hải lý tính từ ranh giới quốc gia hướng tới Bắc cực;', false, 90867);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (93465, 'Các quốc gia vành đai giáp với vùng Bắc cực có được các vùng nước nội thủy, lãnh hải, tiếp giáp lãnh hải, đặc quyền kinh tế, thềm lục địa như các vùng biển khác.', false, 90867);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status) VALUES (90868, 'Việt Nam áp dụng quy tắc nào của Công pháp quốc tế để xác định đường cơ sở dùng để tính chiều rộng lãnh hải ?', 'MULTIPLE_CHOICE', 90018, 9999, 'PRIVATE');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (93466, 'Dựa vào mực nước biển thấp nhất giáp với bờ biển và chạy dọc theo bờ biển, đường nối những điểm nhô ra nhất của bờ biển và tất cả các đảo ven bờ ở mực nước thấp nhất;', false, 90868);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (93467, 'Theo Tuyên bố ngày 12 tháng 5 năm 1977 của Chính phủ nước Cộng hoà xã hội Chủ nghĩa Việt Nam về đường cơ sở dùng để tính chiều rộng lãnh hải Việt Nam;', false, 90868);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (93468, 'Quy tắc đường gãy khúc nối liền các điểm nhô ra dọc bờ biển và các đảo gần bờ do Chính phủ nước Cộng hoà xã hội Chủ nghĩa Việt Nam xác định và công bố;', true, 90868);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (93469, 'Đường ngấn nước thuỷ triều thấp nhất được chọn dùng để tính chiều rộng lãnh hải của theo tuyên bố của Chính phủ.', false, 90868);
